/* Xidecode :: Guía 9 · Introducción a AJAX */
(function () {
  var H = JT.H, C = JT.C, J = JT.J, eq = JT.eq;
  var URL = 'https://mock.xidecode.dev';

  JT.topics.push({
    id: 'g9', num: 9, guide: 'Guía 9', title: 'Introducción a AJAX', short: 'AJAX', color: '#61afef', server: true,
    summary: 'Pide y envía datos al servidor sin recargar la página usando XMLHttpRequest y JSON.',

    theory: [
      { icon: 'globe', h: '¿Qué es AJAX?', html: '<p><b>AJAX</b> significa <i>Asynchronous JavaScript And XML</i>: JavaScript <b>asíncrono</b> y XML. Es una técnica (no un lenguaje) para pedir o enviar datos al servidor <b>sin recargar la página</b>. Hoy casi siempre se intercambia JSON en lugar de XML.</p><p>Une varias tecnologías: HTML/CSS para la presentación, el DOM para actualizar la página, JSON o XML para los datos, <code>XMLHttpRequest</code> para la comunicación y JavaScript para pegarlo todo.</p>', analogy: 'Pedir comida a domicilio: haces el pedido y <b>sigues con tu vida</b> (asíncrono). Cuando llega, lo recibes. Lo contrario (síncrono) sería quedarte parado en la puerta sin hacer nada hasta que llegue.' },
      { icon: 'refresh', h: 'Modelo tradicional vs. AJAX', html: '<p><b>Tradicional:</b> cada clic pide una página nueva completa al servidor y el navegador la vuelve a dibujar. Mientras espera, ves la pantalla en blanco.</p><p><b>Con AJAX:</b> aparece una capa intermedia (tu JavaScript) que pide al servidor <b>solo los datos</b> que faltan y actualiza <b>solo esa parte</b> de la página. La aplicación responde más rápido y el usuario nunca ve una ventana vacía.</p>' },
      { icon: 'code', h: 'XMLHttpRequest en 4 pasos', html: '<ol><li><b>Crear</b> el objeto: <code>var xhr = new XMLHttpRequest();</code></li><li><b>Configurar</b> con <code>open(metodo, url)</code>.</li><li><b>Escuchar</b> la respuesta con <code>onreadystatechange</code> (o <code>onload</code>).</li><li><b>Enviar</b> con <code>send()</code>.</li></ol><p><code>open</code> acepta un tercer parámetro: <code>true</code> (por defecto) hace la petición <b>asíncrona</b>; <code>false</code> la hace <b>síncrona</b> y congela el navegador, así que se evita.</p>', code: 'var xhr = new XMLHttpRequest();\nxhr.open("GET", "https://mock.xidecode.dev/books");\nxhr.onload = function () { console.log(xhr.responseText); };\nxhr.send();' },
      { icon: 'flag', h: 'readyState y status', html: '<p><code>readyState</code> dice en qué etapa va la petición:</p><table><tr><th>Valor</th><th>Significado</th></tr><tr><td>0</td><td>Creada, aún sin <code>open</code></td></tr><tr><td>1</td><td><code>open</code> ya se llamó</td></tr><tr><td>2</td><td><code>send</code> llamado, llegaron las cabeceras</td></tr><tr><td>3</td><td>Recibiendo datos</td></tr><tr><td>4</td><td><b>Completa</b></td></tr></table><p><code>status</code> es el código HTTP: <b>200</b> todo bien, <b>404</b> no existe, <b>500</b> falló el servidor. Para usar la respuesta comprueba <code>readyState == 4 &amp;&amp; status == 200</code>.</p><p>Ojo con los nombres: la guía los llama <i>0 No inicializado, 1 Cargando, 2 Cargado, 3 Interactivo, 4 Completo</i>; la especificación actual los llama <i>UNSENT, OPENED, HEADERS_RECEIVED, LOADING, DONE</i>. Son los mismos cinco estados.</p>' },
      { icon: 'arrow', h: 'GET y POST', html: '<p><b>GET</b> pide datos; los parámetros viajan en la URL y <code>send(null)</code> no envía contenido.</p><p><b>POST</b> envía datos para crear algo: van en el cuerpo, dentro de <code>send(datos)</code>. Antes de enviar JSON conviene avisar con <code>setRequestHeader("Content-Type", "application/json")</code> y convertir el objeto con <code>JSON.stringify</code>.</p>', analogy: 'GET es <b>preguntar</b> "¿qué libros hay?". POST es <b>entregar un formulario</b> "agreguen este libro nuevo".', code: 'xhr.open("POST", url);\nxhr.setRequestHeader("Content-Type", "application/json");\nxhr.send(JSON.stringify({ title: "Mi libro" }));' },
      { icon: 'db', h: 'El servidor de práctica', html: '<p>La guía usa <b>mockAPI.io</b>, un servicio que crea APIs de prueba con datos falsos (necesitas crear una cuenta). Aquí no hace falta: Xidecode incluye un servidor equivalente en <code>https://mock.xidecode.dev</code> con estos recursos:</p><ul><li><code>/books</code>: libros (título, autor, descripción, imagen)</li><li><code>/cities</code>: ciudades (nombre, imagen, descripción)</li><li><code>/users</code> y <code>/todos</code></li></ul><p>Funciona con GET, POST, PUT y DELETE. Si pides un recurso que no existe, devuelve <b>404</b>. En tu práctica real solo cambias la URL por la de tu cuenta de mockAPI.</p>' }
    ],

    examples: [
      /* 1 */
      { id: 'g9e1', title: 'La página sigue viva: asíncrono', short: 'Un reloj que no se detiene mientras llega la respuesta',
        intro: '<p>Este ejemplo prueba por qué AJAX es <b>asíncrono</b>. Pedimos una respuesta <b>lenta</b> (tarda 2,5 segundos). Mientras llega, el reloj de la página <b>sigue contando</b>: la página no se congela ni se recarga.</p>',
        parts: [
          H('<p>Reloj: <b id="reloj">0</b> segundos</p>\n<button id="pedir">Pedir respuesta lenta</button>\n<p id="resultado">Aún no pediste nada.</p>', 'Un contador de segundos, un botón y un párrafo para el resultado.'),
          J('var segundos = 0;\nsetInterval(function () {\n  segundos++;\n  document.getElementById("reloj").textContent = segundos;\n}, 1000);', '<code>setInterval</code> ejecuta la función cada 1000 ms. Es un reloj independiente que demuestra si la página está "viva" o congelada.'),
          J('document.getElementById("pedir").onclick = function () {\n  var xhr = new XMLHttpRequest();\n  xhr.open("GET", "' + URL + '/lento", true);', 'Al pulsar el botón creamos el objeto <code>XMLHttpRequest</code> y configuramos la petición: método <code>GET</code>, la URL y <code>true</code> (asíncrona).'),
          J('  document.getElementById("resultado").textContent = "Esperando respuesta...";\n  xhr.onload = function () {\n    document.getElementById("resultado").textContent = xhr.responseText;\n  };\n  xhr.send();\n};', 'Mostramos "Esperando..." de inmediato. <code>onload</code> define qué hacer cuando <b>por fin llegue</b> la respuesta. <code>send()</code> la envía y el código continúa sin esperar.')
        ],
        notes: [{ type: 'tip', html: 'Pulsa el botón y mira el reloj: sigue subiendo durante los 2,5 segundos. Con una petición <b>síncrona</b> (tercer parámetro <code>false</code>) el reloj se quedaría congelado.' }],
        tryit: ['Cambia <code>/lento</code> por <code>/saludo.txt</code>: la respuesta llega casi al instante.', 'Cambia el segundo del <code>setInterval</code> (1000) por 200 para que el reloj vaya más rápido.'] },
      /* 2 */
      { id: 'g9e2', title: 'Tu primera petición GET', short: 'Crear, configurar, escuchar y enviar',
        intro: '<p>Los cuatro pasos de siempre: <b>crear</b> el objeto, <b>configurar</b> con <code>open</code>, <b>escuchar</b> con <code>onreadystatechange</code> y <b>enviar</b> con <code>send</code>. Aquí pedimos un archivo de texto del servidor de práctica.</p>',
        parts: [
          H('<button id="boton">Pedir saludo</button>\n<p id="resultado"></p>', 'Un botón y un párrafo vacío.'),
          J('var xhr = new XMLHttpRequest();', '<b>Paso 1.</b> <code>new XMLHttpRequest()</code> crea el objeto que hará la petición. Es lo único que hace falta para empezar.'),
          J('xhr.open("GET", "' + URL + '/saludo.txt", true);', '<b>Paso 2.</b> <code>open(método, url, asíncrona)</code> <b>prepara</b> la petición pero todavía no la envía.'),
          J('xhr.onreadystatechange = function () {\n  if (xhr.readyState == 4 && xhr.status == 200) {\n    document.getElementById("resultado").textContent = xhr.responseText;\n  }\n};', '<b>Paso 3.</b> Esta función se llama <b>cada vez que cambia</b> <code>readyState</code>. Solo nos interesa cuando vale <b>4</b> (completa) y <code>status</code> es <b>200</b> (éxito); entonces mostramos <code>responseText</code>.'),
          J('document.getElementById("boton").onclick = function () {\n  xhr.send(null);\n};', '<b>Paso 4.</b> <code>send(null)</code> envía la petición. <code>null</code> significa "no envío datos" (es un GET). Lo conectamos al botón para que se envíe al hacer clic.')
        ],
        notes: [{ type: 'warn', html: 'Una vez enviada, esa misma petición no puede reutilizarse. Si pulsas el botón dos veces dará error; en el ejemplo 9 verás cómo crear una petición nueva en cada clic.' }],
        tryit: ['Pulsa el botón dos veces seguidas y lee el cuadro de error.', 'Cambia <code>saludo.txt</code> por <code>datos.json</code> y observa qué texto llega.'] },
      /* 3 */
      { id: 'g9e3', title: 'Los 5 estados: readyState', short: 'Mira cómo avanza la petición de 0 a 4',
        intro: '<p>La propiedad <code>readyState</code> cambia varias veces durante una petición. Este ejemplo imprime <b>cada cambio</b> para que veas la secuencia completa: <b>0 → 1 → 2 → 3 → 4</b>.</p>',
        parts: [
          H('<button id="go">Iniciar petición</button>\n<ol id="log"></ol>', 'Un botón y una lista ordenada para registrar cada estado.'),
          J('var nombres = [\n  "0 · UNSENT (creada, sin open)",\n  "1 · OPENED (open ya se llamó)",\n  "2 · HEADERS_RECEIVED (llegaron las cabeceras)",\n  "3 · LOADING (recibiendo datos)",\n  "4 · DONE (completa)"\n];', 'Un arreglo con la descripción de cada estado. El número de estado sirve como <b>posición</b> dentro del arreglo.'),
          J('function anotar(xhr) {\n  document.getElementById("log").innerHTML += "<li>" + nombres[xhr.readyState] + " | status: " + xhr.status + "</li>";\n}', 'Cada vez que se llame, agrega a la lista el texto del estado actual y el <code>status</code>. Observa que <code>status</code> vale 0 hasta que el servidor responde.'),
          J('document.getElementById("go").onclick = function () {\n  document.getElementById("log").innerHTML = "";\n  var xhr = new XMLHttpRequest();\n  anotar(xhr);\n  xhr.onreadystatechange = function () {\n    anotar(xhr);\n  };\n  xhr.open("GET", "' + URL + '/books");\n  xhr.send();\n};', 'Antes de llamar a <code>open</code> anotamos el estado 0. Luego <code>onreadystatechange</code> anotará cada cambio: el 1 aparece justo al llamar a <code>open</code>, el 2 y el 3 mientras la respuesta llega y el 4 al terminar.')
        ],
        notes: [{ type: 'info', html: 'El estado 4 <b>no significa éxito</b>, solo que la petición terminó. Revisa también <code>status</code>: prueba cambiar <code>/books</code> por <code>/noexiste</code> y verás que igual llega al 4, pero con status 404.' }],
        tryit: ['Cambia la URL por <code>/noexiste</code>.', 'Mueve <code>xhr.onreadystatechange = ...</code> después de <code>xhr.send()</code> y mira si cambia algo (en una petición real casi siempre funciona, pero es mala costumbre).'] },
      /* 4 */
      { id: 'g9e4', title: 'status y statusText: 200, 404 y 500', short: 'Lee el código que devuelve el servidor',
        intro: '<p>El servidor responde con un <b>código de estado</b>: <b>200</b> (todo bien), <b>404</b> (no existe) o <b>500</b> (falló el servidor). <code>status</code> da el número y <code>statusText</code> el texto equivalente.</p>',
        parts: [
          H('<button data-ruta="/saludo.txt">Pedir algo que existe</button>\n<button data-ruta="/noexiste">Pedir algo que no existe</button>\n<button data-ruta="/error500">Provocar error del servidor</button>\n<pre id="salida">Elige un botón.</pre>', 'Tres botones. Cada uno guarda la ruta que pedirá en un atributo <code>data-ruta</code>.'),
          J('function pedir(ruta) {\n  var xhr = new XMLHttpRequest();\n  xhr.open("GET", "' + URL + '" + ruta);', 'Una función reutilizable: recibe la <b>ruta</b> y crea una petición nueva cada vez (así evitamos el problema de reutilizar una petición ya enviada).'),
          J('  xhr.onload = function () {\n    var texto = "status: " + xhr.status + "\\nstatusText: " + xhr.statusText;\n    if (xhr.status == 200) {\n      texto += "\\n¡Éxito!";\n    } else if (xhr.status == 404) {\n      texto += "\\nEse recurso no existe.";\n    } else {\n      texto += "\\nAlgo falló en el servidor.";\n    }\n    document.getElementById("salida").textContent = texto;\n  };\n  xhr.send();\n}', '<code>onload</code> se ejecuta al terminar aunque sea con error HTTP. Usamos <code>if / else if / else</code> para reaccionar distinto según <code>status</code>. <code>\\n</code> es un salto de línea.'),
          J('var botones = document.getElementsByTagName("button");\nfor (var i = 0; i < botones.length; i++) {\n  botones[i].onclick = function () {\n    pedir(this.getAttribute("data-ruta"));\n  };\n}', 'Recorremos todos los botones y a cada uno le asignamos un clic. Dentro del clic, <code>this</code> es el botón pulsado y <code>getAttribute("data-ruta")</code> lee la ruta que guardó.')
        ],
        tryit: ['Agrega un cuarto botón con <code>data-ruta="/books/3"</code> y otro con <code>/books/99</code>.', 'Muestra también el contenido de <code>xhr.responseText</code>.'] },
      /* 5 */
      { id: 'g9e5', title: 'Respuesta JSON: de responseText a objeto', short: 'Pide libros y muéstralos en una lista',
        intro: '<p>El servidor entrega los libros como <b>texto JSON</b> en <code>responseText</code>. Con <code>JSON.parse</code> lo conviertes en un arreglo de objetos y lo recorres para construir la lista. Este es el patrón más usado en AJAX.</p>',
        parts: [
          H('<h3>Libros disponibles</h3>\n<ul id="libros"></ul>', 'Una lista vacía que llenaremos con datos del servidor.'),
          J('var xhr = new XMLHttpRequest();\nxhr.open("GET", "' + URL + '/books", true);', 'Preparamos un GET al recurso <code>/books</code>.'),
          J('xhr.onreadystatechange = function () {\n  if (xhr.readyState == 4 && xhr.status == 200) {\n    var libros = JSON.parse(xhr.responseText);\n    mostrar(libros);\n  }\n};', 'Cuando la petición termina bien, <code>JSON.parse</code> convierte el texto en un <b>arreglo</b> de objetos y se lo pasamos a <code>mostrar</code>.'),
          J('function mostrar(libros) {\n  var ul = document.getElementById("libros");\n  for (var i = 0; i < libros.length; i++) {\n    ul.innerHTML += "<li><b>" + libros[i].title + "</b> de " + libros[i].author + "</li>";\n  }\n}', 'Recorremos el arreglo. <code>libros[i].title</code> es la propiedad <code>title</code> del libro en la posición <code>i</code>. Cada vuelta agrega un <code>&lt;li&gt;</code>.'),
          J('xhr.send(null);', 'Por último se envía. Como la respuesta llega después, el orden en el código no importa mientras <code>onreadystatechange</code> esté definido <b>antes</b> de <code>send</code>.')
        ],
        notes: [{ type: 'tip', html: 'Mira en la pestaña <b>Consola</b>: si agregas <code>console.log(xhr.responseText)</code> verás el JSON crudo tal como llega (un texto largo).' }],
        tryit: ['Muestra también la descripción: <code>libros[i].description</code>.', 'Cambia <code>/books</code> por <code>/users</code> y muestra <code>name</code> y <code>email</code>.'] },
      /* 6 */
      { id: 'g9e6', title: 'onload y onerror', short: 'Distingue "respondió con error" de "no hubo conexión"',
        intro: '<p><code>onload</code> es una forma más sencilla que <code>onreadystatechange</code> y se ejecuta cuando la respuesta llegó (aunque sea 404). <code>onerror</code> se ejecuta solo cuando <b>no se pudo hacer la petición</b> (sin red, servidor inalcanzable).</p>',
        parts: [
          H('<button id="ok">Servidor de práctica</button>\n<button id="malo">Servidor que no existe</button>\n<p id="estado">Elige un botón.</p>', 'Dos botones: uno a un servidor que existe y otro a uno que no.'),
          J('function pedir(url) {\n  var estado = document.getElementById("estado");\n  estado.textContent = "Cargando...";\n  var xhr = new XMLHttpRequest();\n  xhr.open("GET", url);', 'Función que pide cualquier URL y muestra "Cargando..." mientras espera.'),
          J('  xhr.onload = function () {\n    estado.textContent = "Respondió con código " + xhr.status;\n  };\n  xhr.onerror = function () {\n    estado.textContent = "Error de red: no se pudo conectar";\n  };\n  xhr.send();\n}', '<code>onload</code> recibe cualquier respuesta del servidor (200, 404...). <code>onerror</code> solo salta si la conexión falla del todo. Son casos distintos.'),
          J('document.getElementById("ok").onclick = function () {\n  pedir("' + URL + '/books");\n};\ndocument.getElementById("malo").onclick = function () {\n  pedir("https://servidor-que-no-existe.dev/datos");\n};', 'El primer botón pide un recurso real; el segundo, un servidor que no existe para provocar <code>onerror</code>.')
        ],
        tryit: ['Cambia la ruta del primer botón por <code>/noexiste</code>: sigue entrando por <code>onload</code> con 404.', 'Agrega <code>xhr.timeout = 1000;</code> y <code>xhr.ontimeout = ...</code> y pide <code>/lento</code>.'] },
      /* 7 */
      { id: 'g9e7', title: 'Cargar contenido al pasar el ratón', short: 'Ejercicio 1 de la guía: portadas y descripción',
        intro: '<p>Este es el ejercicio 1 de la guía: al colocar el ratón sobre la portada de un libro se hace una petición AJAX y se muestra su información en un recuadro. Al retirarlo, el recuadro se vacía. Se registran los eventos <code>mouseover</code> y <code>mouseout</code> con compatibilidad entre navegadores.</p>',
        parts: [
          H('<div class="fila">\n  <div class="portada" id="java8" style="background:#3b82c4">Java 8</div>\n  <div class="portada" id="jsninja" style="background:#8a4bb0">JS Ninja</div>\n  <div class="portada" id="nodejs" style="background:#3a8a4e">Node.js</div>\n</div>\n<div id="detalle">Pasa el ratón sobre una portada.</div>', 'Tres "portadas" (cajas de color) con un <code>id</code> cada una y un recuadro <code>detalle</code> donde aparecerá la información.'),
          C('.fila { display: flex; gap: 14px; margin-bottom: 14px; }\n.portada { width: 96px; height: 130px; border-radius: 6px; color: #fff; font-weight: 700; display: grid; place-items: center; cursor: pointer; box-shadow: 0 4px 10px rgba(0,0,0,.25); }\n#detalle { min-height: 70px; border: 1px dashed #98a2b8; padding: 10px; border-radius: 8px; }', 'Las portadas se dibujan con CSS: tamaño fijo, color de fondo propio y cursor de "mano".'),
          J('function obtenerContenido(id) {\n  var xhr = new XMLHttpRequest();\n  xhr.open("GET", "' + URL + '/books/" + id, true);\n  xhr.onreadystatechange = function () {\n    if (xhr.readyState == 4 && xhr.status == 200) {\n      var libro = JSON.parse(xhr.responseText);\n      document.getElementById("detalle").innerHTML = "<b>" + libro.title + "</b><br>" + libro.author + "<br>" + libro.description;\n    }\n  };\n  xhr.send(null);\n}', 'Pide <code>/books/<i>id</i></code> y, al llegar, convierte el JSON en objeto y muestra título, autor y descripción dentro del recuadro.'),
          J('function borrarContenido() {\n  document.getElementById("detalle").innerHTML = "";\n}', 'Vacía el recuadro cuando el ratón sale de la portada.'),
          J('function registrar(elemento, evento, funcion) {\n  if (elemento.addEventListener) {\n    elemento.addEventListener(evento, funcion, false);\n  } else if (elemento.attachEvent) {\n    elemento.attachEvent("on" + evento, funcion);\n  }\n}', 'Función de <b>compatibilidad</b>: los navegadores modernos usan <code>addEventListener</code>; Internet Explorer antiguo usaba <code>attachEvent</code> (con "on" delante). La guía la repite una vez por cada imagen; aquí la reunimos en una sola.'),
          J('var libros = { java8: "2", jsninja: "3", nodejs: "4" };\n\nfor (var idElemento in libros) {\n  (function (idHtml, idLibro) {\n    var caja = document.getElementById(idHtml);\n    registrar(caja, "mouseover", function () { obtenerContenido(idLibro); });\n    registrar(caja, "mouseout", borrarContenido);\n  })(idElemento, libros[idElemento]);\n}', 'Asociamos cada portada con el id de su libro. El bucle <code>for...in</code> recorre las claves del objeto. La función autoejecutable <code>(function(){...})()</code> guarda el valor correcto de cada vuelta. Cada caja recibe <code>mouseover</code> (pide datos) y <code>mouseout</code> (limpia).')
        ],
        notes: [{ type: 'info', html: 'En la guía el libro 1 también existe; aquí usamos los ids 2, 3 y 4 del servidor de práctica (Java 8, JS Ninja y Node.js).' }],
        tryit: ['Agrega una cuarta portada con id <code>eloquent</code> que apunte al libro <code>"1"</code>.', 'Cambia <code>mouseover</code> por <code>click</code> para que cargue al hacer clic.'] },
      /* 8 */
      { id: 'g9e8', title: 'Menú de navegación con AJAX', short: 'Ejercicio 2 de la guía: ciudades sin recargar',
        intro: '<p>Es el ejercicio 2 de la guía (<code>xmlhttp.js</code>): un menú cuyos enlaces cargan <b>la información de una ciudad</b> con AJAX, sin recargar la página. Incluye la forma clásica de <b>crear el objeto</b> de manera compatible con navegadores muy antiguos (con <code>ActiveXObject</code>).</p>',
        parts: [
          H('<nav>\n  <a href="#" data-id="1">París</a> |\n  <a href="#" data-id="2">Tokio</a> |\n  <a href="#" data-id="3">San Salvador</a> |\n  <a href="#" data-id="4">Roma</a>\n</nav>\n<div class="ciudad">\n  <img id="cityImage" alt="" width="240">\n  <p id="cityDescription">Elige una ciudad del menú.</p>\n</div>', 'Un menú con cuatro enlaces (cada uno con el <code>id</code> de su ciudad en <code>data-id</code>) y un recuadro con una imagen y una descripción.'),
          C('nav a { color: #3b82c4; font-weight: 600; text-decoration: none; }\nnav a:hover { text-decoration: underline; }\n.ciudad { margin-top: 12px; }\nimg { border-radius: 8px; display: block; margin-bottom: 8px; }', 'Estilos sencillos para el menú y la imagen.'),
          J('var xmlhttp = false;\n\ntry {\n  xmlhttp = new ActiveXObject("Msxml2.XMLHTTP");\n} catch (e) {\n  try {\n    xmlhttp = new ActiveXObject("Microsoft.XMLHTTP");\n  } catch (E) {\n    xmlhttp = false;\n  }\n}\n\nif (!xmlhttp && typeof XMLHttpRequest != "undefined") {\n  xmlhttp = new XMLHttpRequest();\n}', 'Código de <b>compatibilidad histórica</b>. Primero intenta crear el objeto con <code>ActiveXObject</code> (Internet Explorer 5/6). Si falla (<code>catch</code>), prueba otra versión; si también falla, queda en <code>false</code>. Al final, si no se creó y existe <code>XMLHttpRequest</code>, se usa el moderno. En navegadores actuales entra directo por el último <code>if</code>.'),
          J('function makerequest(id) {\n  var URL = "' + URL + '/cities/" + id;\n  xmlhttp.open("GET", URL, true);\n  xmlhttp.onreadystatechange = function () {\n    if (xmlhttp.readyState == 4 && xmlhttp.status == 200) {\n      var cityJson = JSON.parse(xmlhttp.responseText);\n      document.getElementById("cityImage").src = cityJson.image;\n      document.getElementById("cityDescription").innerHTML = cityJson.description;\n    }\n  };\n  xmlhttp.send(null);\n}', 'Pide <code>/cities/<i>id</i></code> y, al llegar, usa el JSON para cambiar el <code>src</code> de la imagen y el texto de la descripción. En tu mockAPI real solo cambiarías la constante <code>URL</code>.'),
          J('var enlaces = document.getElementsByTagName("a");\nfor (var i = 0; i < enlaces.length; i++) {\n  enlaces[i].onclick = function (e) {\n    e.preventDefault();\n    xmlhttp = new XMLHttpRequest();\n    makerequest(this.getAttribute("data-id"));\n  };\n}', 'A cada enlace le asignamos un clic. <code>preventDefault()</code> evita que el navegador siga el enlace <code>#</code>. Creamos un <b>objeto nuevo</b> en cada clic porque una petición ya enviada no se puede reutilizar.')
        ],
        tryit: ['Agrega una quinta ciudad: busca en el servidor con <code>/cities</code> cuántas hay y prueba <code>data-id="5"</code> (verás el 404).', 'Muestra también el nombre de la ciudad: <code>cityJson.name</code>.'] },
      /* 9 */
      { id: 'g9e9', title: 'POST: crear un recurso', short: 'Envía JSON al servidor con setRequestHeader y send',
        intro: '<p>Con <b>POST</b> enviamos datos al servidor para crear algo. Usamos <code>setRequestHeader</code> para avisar que el cuerpo es JSON y <code>JSON.stringify</code> para convertir el objeto en texto. El servidor responde con el elemento creado y el código <b>201</b>.</p>',
        parts: [
          H('<h3>Agregar un libro</h3>\n<input type="text" id="titulo" placeholder="Título">\n<input type="text" id="autor" placeholder="Autor">\n<button id="crear">Crear libro</button>\n<pre id="respuesta">Aquí verás la respuesta.</pre>', 'Dos campos, un botón y un recuadro para ver la respuesta del servidor.'),
          J('document.getElementById("crear").onclick = function () {\n  var libro = {\n    title: document.getElementById("titulo").value,\n    author: document.getElementById("autor").value,\n    description: "Creado desde Xidecode"\n  };', 'Al pulsar, armamos el objeto <code>libro</code> con lo escrito en los campos (<code>.value</code>).'),
          J('  var xhr = new XMLHttpRequest();\n  xhr.open("POST", "' + URL + '/books", true);\n  xhr.setRequestHeader("Content-Type", "application/json");', 'Creamos una petición <b>POST</b> al recurso <code>/books</code>. <code>setRequestHeader</code> se llama <b>después</b> de <code>open</code> y <b>antes</b> de <code>send</code>: dice al servidor que enviamos JSON.'),
          J('  xhr.onload = function () {\n    document.getElementById("respuesta").textContent = "Código: " + xhr.status + " " + xhr.statusText + "\\n" + xhr.responseText;\n  };', 'Mostramos el código (esperamos <b>201 Created</b>) y el texto que devuelve el servidor, que incluye el libro con su nuevo <code>id</code>.'),
          J('  xhr.send(JSON.stringify(libro));\n};', '<code>send</code> recibe ahora el contenido: el objeto convertido en texto con <code>JSON.stringify</code>.')
        ],
        notes: [{ type: 'tip', html: 'Después de crear un libro, abre el ejemplo 5 (lista de libros): ahora aparece también el tuyo. Usa "Reiniciar servidor" bajo la pantalla para volver a los datos originales.' }],
        tryit: ['Crea un libro sin escribir nada y mira la respuesta.', 'Cambia <code>"POST"</code> por <code>"GET"</code> y observa qué ocurre con el cuerpo.'] },
      /* 10 */
      { id: 'g9e10', title: 'Cabeceras de la respuesta', short: 'getResponseHeader y getAllResponseHeaders',
        intro: '<p>Cada respuesta HTTP trae <b>cabeceras</b>: datos sobre la respuesta (tipo de contenido, servidor...). <code>getResponseHeader("nombre")</code> lee una y <code>getAllResponseHeaders()</code> las devuelve todas en un texto.</p>',
        parts: [
          H('<button id="go">Pedir y mostrar cabeceras</button>\n<pre id="salida"></pre>', 'Un botón y un recuadro de texto.'),
          J('document.getElementById("go").onclick = function () {\n  var xhr = new XMLHttpRequest();\n  xhr.open("GET", "' + URL + '/datos.json");\n  xhr.setRequestHeader("Accept", "application/json");', 'Preparamos un GET. Con <code>setRequestHeader("Accept", ...)</code> también podemos agregar cabeceras a <b>nuestra petición</b>.'),
          J('  xhr.onload = function () {\n    var tipo = xhr.getResponseHeader("Content-Type");\n    var todas = xhr.getAllResponseHeaders();\n    document.getElementById("salida").textContent =\n      "Tipo de contenido: " + tipo + "\\n\\nTodas las cabeceras:\\n" + todas;\n  };\n  xhr.send();\n};', '<code>getResponseHeader("Content-Type")</code> devuelve el tipo de contenido de la respuesta. <code>getAllResponseHeaders()</code> devuelve un texto con todas, una por línea.')
        ],
        tryit: ['Cambia <code>datos.json</code> por <code>noticias.html</code> y compara el <code>Content-Type</code>.', 'Lee otra cabecera: <code>xhr.getResponseHeader("x-servidor")</code>.'] },
      /* 11 */
      { id: 'g9e11', title: 'El orden del código asíncrono', short: 'Por qué "después" aparece antes que la respuesta',
        intro: '<p>Una de las cosas que más confunde al empezar: el código <b>sigue ejecutándose</b> después de <code>send()</code> sin esperar la respuesta. Mira el orden de los mensajes en la consola: no coincide con el orden de las líneas.</p>',
        parts: [
          H('<button id="go">Ejecutar</button>\n<p>Abre la pestaña <b>Consola</b> para ver el orden.</p>', 'Un botón; el resultado está en la consola.'),
          J('document.getElementById("go").onclick = function () {\n  console.log("1. Antes de enviar");\n  var xhr = new XMLHttpRequest();\n  xhr.open("GET", "' + URL + '/saludo.txt", true);', 'Primer mensaje: se ejecuta de inmediato.'),
          J('  xhr.onload = function () {\n    console.log("3. Llegó la respuesta: " + xhr.responseText);\n  };\n  xhr.send();\n  console.log("2. Después de enviar (la respuesta aún no llega)");\n};', 'El mensaje "3" está <b>antes</b> en el código pero se ejecuta <b>al final</b>, porque <code>onload</code> solo se llama cuando llega la respuesta. El mensaje "2" sí se ejecuta justo después de <code>send()</code>.')
        ],
        notes: [{ type: 'warn', html: '<b>Error muy común:</b> intentar usar la respuesta justo después de <code>send()</code>. Todavía no existe. Todo lo que dependa de la respuesta debe ir <b>dentro</b> de <code>onload</code> / <code>onreadystatechange</code>.' }, { type: 'info', html: 'Si el tercer parámetro de <code>open</code> fuera <code>false</code> (síncrono), el orden sería 1, 3, 2... pero la página se congelaría mientras espera. Por eso no se recomienda.' }],
        tryit: ['Cambia la URL por <code>/lento</code> y observa cuánto tarda en aparecer el mensaje 3 (el 2 sale enseguida).', 'Prueba cambiando el tercer parámetro de <code>open</code> a <code>false</code> y mira cómo cambia el orden.'] },
      /* 12 */
      { id: 'g9e12', title: 'fetch(): la alternativa moderna', short: 'Lo mismo con promesas y .then()',
        intro: '<p>Hoy, además de <code>XMLHttpRequest</code>, los navegadores traen <code>fetch()</code>, que devuelve una <b>promesa</b>: encadenas <code>.then()</code> para cada paso y <code>.catch()</code> para los errores. Es más corto y se lee mejor. Entender XMLHttpRequest te ayuda a comprender qué hace por debajo.</p>',
        parts: [
          H('<h3>Ciudades (con fetch)</h3>\n<ul id="ciudades"></ul>\n<p id="estado"></p>', 'Una lista para las ciudades y un párrafo para mensajes.'),
          J('fetch("' + URL + '/cities")', '<code>fetch(url)</code> envía un GET y devuelve una <b>promesa</b>.'),
          J('  .then(function (respuesta) {\n    if (!respuesta.ok) {\n      throw new Error("Código " + respuesta.status);\n    }\n    return respuesta.json();\n  })', 'Primer <code>.then</code>: recibe la respuesta. <code>respuesta.ok</code> es <code>true</code> si el código fue 2xx. <code>respuesta.json()</code> lee el cuerpo y lo convierte (equivale a <code>JSON.parse(responseText)</code>) y devuelve otra promesa.'),
          J('  .then(function (ciudades) {\n    var ul = document.getElementById("ciudades");\n    ciudades.forEach(function (c) {\n      ul.innerHTML += "<li>" + c.name + "</li>";\n    });\n  })\n  .catch(function (error) {\n    document.getElementById("estado").textContent = "Falló: " + error.message;\n  });', 'Segundo <code>.then</code>: ya recibe el arreglo de ciudades. <code>forEach</code> ejecuta una función por cada elemento. <code>.catch</code> atrapa cualquier error de la cadena (red, código distinto de 2xx...).')
        ],
        tryit: ['Cambia <code>/cities</code> por <code>/noexiste</code> y observa el mensaje del <code>catch</code>.', 'Muestra la descripción de cada ciudad junto al nombre.'] }
    ],

    exercises: [
      /* X1 */
      { id: 'g9x1', title: 'Tu primera petición GET', short: 'Los cuatro pasos de XMLHttpRequest, línea a línea', lib: null,
        goal: '<p>Vas a pedir un saludo al servidor de práctica y mostrarlo en la página, escribiendo tú mismo los cuatro pasos de una petición AJAX.</p>',
        base: { html: '<h2>Saludo del servidor</h2>\n<p id="resultado">Esperando...</p>', js: '// tu código aquí' },
        steps: [
          { file: 'js', title: 'Crea el objeto', instr: 'Crea una variable <code>xhr</code> con un nuevo objeto <code>XMLHttpRequest</code>.', why: '<code>XMLHttpRequest</code> es el objeto del navegador que sabe hacer peticiones. Se crea con <code>new</code>.', hint: '<code>var xhr = new XMLHttpRequest();</code>', sol: 'var xhr = new XMLHttpRequest();', ok: eq('var xhr=new XMLHttpRequest()'), errs: [[/^(?:const|let|var) xhr=XMLHttpRequest/, 'Falta <code>new</code> antes de <code>XMLHttpRequest</code>: es un constructor.']] },
          { file: 'js', type: 'blank', title: 'Configura la petición', instr: 'Completa los huecos para pedir por <b>GET</b> el archivo <code>saludo.txt</code>.', tpl: 'xhr.[[open]]("[[GET]]", "' + URL + '/saludo.txt", [[true]]);', blanks: ['El método que prepara la petición.', 'El método HTTP para pedir datos.', 'Asíncrona = true.'], why: '<code>open(método, url, asíncrona)</code> solo <b>prepara</b> la petición. <code>GET</code> pide datos; <code>true</code> evita congelar el navegador.', hint: 'Los huecos son: <code>open</code>, <code>GET</code> y <code>true</code>.', sol: 'xhr.open("GET", "' + URL + '/saludo.txt", true);' },
          { file: 'js', title: 'Escucha la respuesta', instr: 'Asigna a <code>xhr.onreadystatechange</code> una función que, <b>si readyState es 4 y status es 200</b>, escriba <code>xhr.responseText</code> en el elemento <code>resultado</code>.', multi: true, why: '<code>onreadystatechange</code> se llama cada vez que cambia el estado. Solo cuando vale 4 y el status es 200 la respuesta está completa y buena, entonces la mostramos.', hint: 'xhr.onreadystatechange = function () {\n  if (xhr.readyState == 4 && xhr.status == 200) {\n    document.getElementById("resultado").textContent = xhr.responseText;\n  }\n};', sol: 'xhr.onreadystatechange = function () {\n  if (xhr.readyState == 4 && xhr.status == 200) {\n    document.getElementById("resultado").textContent = xhr.responseText;\n  }\n};',
            ok: function (n) { return /^xhr\.onreadystatechange=function\(\)\{/.test(n) && /readyState(?:==|===)4/.test(n) && /status(?:==|===)200/.test(n) && /document\.getElementById\('resultado'\)\.(?:textContent|innerHTML|innerText)=xhr\.responseText/.test(n) && /\}$/.test(n); }, errs: [[/readyState(?:==|===)[0-3]\b/, 'La petición termina cuando <code>readyState</code> vale <b>4</b>.'], [/readyState=4/, 'Usaste <code>=</code> (asigna). Para comparar se usa <code>==</code> o <code>===</code>.'], [/status(?:==|===)404/, 'Un 404 significa "no encontrado". Para éxito el código es <b>200</b>.']] },
          { file: 'js', title: 'Envía la petición', instr: 'Envía la petición sin datos.', why: '<code>send(null)</code> envía la petición. Es el paso que realmente la lanza; <code>null</code> indica que no hay contenido (GET).', hint: '<code>xhr.send(null);</code>', sol: 'xhr.send(null);', ok: /^xhr\.send\((?:null)?\)$/, errs: [[/xhr\.send\((?!null\)).+\)/, 'En un GET no se envían datos: usa <code>null</code>.']] },
          { file: 'js', title: 'Comprueba el orden', instr: 'Escribe una línea que muestre en la consola el texto <code>"La página sigue viva"</code>.', why: 'Esta línea se ejecuta <b>antes</b> de que llegue la respuesta. Compruébalo en la consola: eso es lo que significa "asíncrono".', hint: '<code>console.log("La página sigue viva");</code>', sol: 'console.log("La página sigue viva");', ok: eq("console.log('La página sigue viva')") }
        ], final: 'Abre la pantalla y mira el resultado. Fíjate en la consola: "La página sigue viva" aparece <b>antes</b> de que el saludo llegue.' },
      /* X2 */
      { id: 'g9x2', title: 'Mostrar los libros en una lista', short: 'GET + JSON.parse + bucle for', lib: null,
        goal: '<p>Vas a pedir la lista de libros al servidor, convertir el JSON en un arreglo y pintar una lista con el título y el autor de cada uno.</p>',
        base: { html: '<h2>Libros</h2>\n<ul id="libros"></ul>', js: '// tu código aquí' },
        steps: [
          { file: 'js', title: 'Crea la petición', instr: 'Crea la variable <code>xhr</code> con un nuevo <code>XMLHttpRequest</code>.', why: 'Siempre el primer paso.', hint: '<code>var xhr = new XMLHttpRequest();</code>', sol: 'var xhr = new XMLHttpRequest();', ok: eq('var xhr=new XMLHttpRequest()') },
          { file: 'js', type: 'blank', title: 'Configura el GET', instr: 'Completa para pedir el recurso <code>/books</code>.', tpl: 'xhr.open("GET", "' + URL + '/[[books]]");', blanks: ['Es el nombre del recurso de libros del servidor.'], why: 'La URL termina en el nombre del recurso: <code>/books</code> devuelve el arreglo de libros.', hint: 'El recurso se llama <code>books</code>.', sol: 'xhr.open("GET", "' + URL + '/books");' },
          { file: 'js', title: 'Abre el manejador onload', instr: 'Escribe la primera línea del manejador: <code>xhr.onload = function () {</code>', why: '<code>onload</code> se ejecuta cuando la respuesta llegó. Todo lo que dependa de los datos debe ir dentro.', hint: '<code>xhr.onload = function () {</code>', sol: 'xhr.onload = function () {', ok: eq('xhr.onload=function(){') },
          { file: 'js', indent: 1, title: 'Convierte el JSON', instr: 'Dentro, crea la variable <code>libros</code> con el resultado de <code>JSON.parse(xhr.responseText)</code>.', why: '<code>responseText</code> es un texto. <code>JSON.parse</code> lo convierte en un arreglo de objetos que sí puedes recorrer.', hint: '<code>var libros = JSON.parse(xhr.responseText);</code>', sol: 'var libros = JSON.parse(xhr.responseText);', ok: eq('var libros=JSON.parse(xhr.responseText)'), errs: [[/JSON\.stringify/, '<code>stringify</code> va de objeto a texto. Aquí necesitas <code>parse</code> (texto a objeto).']] },
          { file: 'js', indent: 1, title: 'Recorre y pinta', instr: 'Con un <code>for</code>, agrega a <code>libros</code> del HTML un <code>&lt;li&gt;</code> con el <b>título</b> y el <b>autor</b> de cada libro (propiedades <code>title</code> y <code>author</code>). Usa <code>document.getElementById("libros").innerHTML +=</code>.', multi: true, why: '<code>libros[i].title</code> es el título del libro en la posición <code>i</code>. Con <code>+=</code> se acumula un <code>&lt;li&gt;</code> por cada libro.', hint: 'for (var i = 0; i < libros.length; i++) {\n  document.getElementById("libros").innerHTML += "<li>" + libros[i].title + " - " + libros[i].author + "</li>";\n}', sol: 'for (var i = 0; i < libros.length; i++) {\n  document.getElementById("libros").innerHTML += "<li>" + libros[i].title + " - " + libros[i].author + "</li>";\n}', ok: function (n) { return /^for\((?:var|let) (\w)=0;\1<libros\.length;\1\+\+\)\{/.test(n) && /document\.getElementById\('libros'\)\.innerHTML\+=/.test(n) && /libros\[\w\]\.title/.test(n) && /libros\[\w\]\.author/.test(n) && /\}$/.test(n); }, errs: [[/innerHTML=/, 'Con <code>=</code> reemplazas el contenido en cada vuelta. Usa <code>+=</code> para acumular.']] },
          { file: 'js', title: 'Cierra el manejador', instr: 'Cierra la función con <code>};</code>', why: 'Termina la función asignada a <code>onload</code>.', hint: '<code>};</code>', sol: '};', ok: /^\}$/ },
          { file: 'js', title: 'Envía', instr: 'Envía la petición.', why: 'Sin <code>send</code> no pasa nada.', hint: '<code>xhr.send();</code>', sol: 'xhr.send();', ok: /^xhr\.send\((?:null)?\)$/ }
        ] },
      /* X3 */
      { id: 'g9x3', title: 'Reaccionar según el status', short: 'Manejo de 200, 404 y 500', lib: null,
        goal: '<p>Una función <code>pedir(ruta)</code> que muestra un mensaje <b>distinto</b> según el código de estado de la respuesta.</p>',
        base: { html: '<button id="bien">Existe</button> <button id="mal">No existe</button> <button id="falla">Falla</button>\n<p id="resultado">Pulsa un botón.</p>', js: 'function mostrar(texto) {\n  document.getElementById("resultado").textContent = texto;\n}\n\n// tu código aquí' },
        steps: [
          { file: 'js', title: 'Abre la función', instr: 'Escribe la primera línea de la función <code>pedir</code> que recibe el parámetro <code>ruta</code>.', why: 'Una función que recibe la ruta nos deja hacer tres peticiones distintas con el mismo código.', hint: '<code>function pedir(ruta) {</code>', sol: 'function pedir(ruta) {', ok: eq('function pedir(ruta){') },
          { file: 'js', indent: 1, title: 'Crea y configura', instr: 'Dentro, crea <code>xhr</code> y haz <code>open</code> de un GET a <code>"' + URL + '" + ruta</code>. (Dos líneas.)', multi: true, why: 'Unimos la dirección base con la <code>ruta</code> que recibimos usando <code>+</code>.', hint: 'var xhr = new XMLHttpRequest();\nxhr.open("GET", "' + URL + '" + ruta);', sol: 'var xhr = new XMLHttpRequest();\nxhr.open("GET", "' + URL + '" + ruta);', ok: function (n) { return /^(?:const|let|var) xhr=new XMLHttpRequest\(\);xhr\.open\('GET','https:\/\/mock.xidecode.dev'\+ruta(?:,true)?\)$/.test(n); } },
          { file: 'js', indent: 1, title: 'Decide según el status', instr: 'Escribe <code>xhr.onload</code> con un <code>if / else if / else</code>: si <code>status</code> es 200 llama <code>mostrar("Éxito: " + xhr.responseText)</code>; si es 404 <code>mostrar("No encontrado (404)")</code>; en otro caso <code>mostrar("Error del servidor: " + xhr.status)</code>.', multi: true, why: 'Cada rama atiende un tipo de respuesta. Así el usuario recibe un mensaje claro, no una pantalla rota.', hint: 'xhr.onload = function () {\n  if (xhr.status == 200) {\n    mostrar("Éxito: " + xhr.responseText);\n  } else if (xhr.status == 404) {\n    mostrar("No encontrado (404)");\n  } else {\n    mostrar("Error del servidor: " + xhr.status);\n  }\n};', sol: 'xhr.onload = function () {\n  if (xhr.status == 200) {\n    mostrar("Éxito: " + xhr.responseText);\n  } else if (xhr.status == 404) {\n    mostrar("No encontrado (404)");\n  } else {\n    mostrar("Error del servidor: " + xhr.status);\n  }\n};', ok: function (n) { return /^xhr\.onload=function\(\)\{if\(xhr\.status(?:==|===)200\)\{mostrar\(/.test(n) && /else if\(xhr\.status(?:==|===)404\)\{mostrar\(/.test(n) && /\}else\{mostrar\(/.test(n) && /\}$/.test(n); }, errs: [[/status=200/, 'Usaste <code>=</code> (asigna). Para comparar usa <code>==</code>.']] },
          { file: 'js', indent: 1, title: 'Envía', instr: 'Envía la petición.', why: 'Último paso dentro de la función.', hint: '<code>xhr.send();</code>', sol: 'xhr.send();', ok: /^xhr\.send\((?:null)?\)$/ },
          { file: 'js', title: 'Cierra la función', instr: 'Cierra la función con <code>}</code>.', why: 'Cierra el bloque abierto en el primer paso.', hint: '<code>}</code>', sol: '}', ok: /^\}$/ },
          { file: 'js', title: 'Conecta los botones', instr: 'Haz que el botón <code>bien</code> llame <code>pedir("/saludo.txt")</code>, <code>mal</code> llame <code>pedir("/noexiste")</code> y <code>falla</code> llame <code>pedir("/error500")</code>, cada uno con su <code>onclick</code>. (Tres líneas.)', multi: true, why: 'Cada botón pide una ruta distinta. Así pruebas los tres casos: 200, 404 y 500.', hint: 'document.getElementById("bien").onclick = function () { pedir("/saludo.txt"); };\ndocument.getElementById("mal").onclick = function () { pedir("/noexiste"); };\ndocument.getElementById("falla").onclick = function () { pedir("/error500"); };', sol: 'document.getElementById("bien").onclick = function () { pedir("/saludo.txt"); };\ndocument.getElementById("mal").onclick = function () { pedir("/noexiste"); };\ndocument.getElementById("falla").onclick = function () { pedir("/error500"); };', ok: function (n) { return /getElementById\('bien'\)\.onclick=function\(\)\{pedir\('\/saludo\.txt'\)\}/.test(n) && /getElementById\('mal'\)\.onclick=function\(\)\{pedir\('\/noexiste'\)\}/.test(n) && /getElementById\('falla'\)\.onclick=function\(\)\{pedir\('\/error500'\)\}/.test(n); } }
        ] },
      /* X4 */
      { id: 'g9x4', title: 'POST: crear un libro', short: 'Envía datos al servidor con POST y JSON', lib: null,
        goal: '<p>Un formulario que <b>crea un libro nuevo</b> en el servidor con una petición POST y muestra la respuesta (código 201 y el libro creado).</p>',
        base: { html: '<h3>Nuevo libro</h3>\n<input type="text" id="titulo" placeholder="Título">\n<input type="text" id="autor" placeholder="Autor">\n<button id="crear">Crear</button>\n<pre id="resultado"></pre>', js: '// tu código aquí' },
        steps: [
          { file: 'js', title: 'Abre el clic del botón', instr: 'Escribe la primera línea del manejador del botón <code>crear</code>: <code>document.getElementById("crear").onclick = function () {</code>', why: 'La petición se hará cada vez que se pulse el botón, así que va dentro de este manejador. Esto también crea un objeto nuevo en cada clic.', hint: '<code>document.getElementById("crear").onclick = function () {</code>', sol: 'document.getElementById("crear").onclick = function () {', ok: eq("document.getElementById('crear').onclick=function(){") },
          { file: 'js', indent: 1, title: 'Arma el objeto', instr: 'Crea el objeto <code>libro</code> con <code>title</code> (valor del campo <code>titulo</code>) y <code>author</code> (valor del campo <code>autor</code>).', multi: true, why: '<code>.value</code> lee lo que el usuario escribió. Los nombres <code>title</code> y <code>author</code> son los que espera el servidor.', hint: 'var libro = {\n  title: document.getElementById("titulo").value,\n  author: document.getElementById("autor").value\n};', sol: 'var libro = {\n  title: document.getElementById("titulo").value,\n  author: document.getElementById("autor").value\n};', ok: function (n) { return /^(?:const|let|var) libro=\{/.test(n) && /title:document\.getElementById\('titulo'\)\.value/.test(n) && /author:document\.getElementById\('autor'\)\.value/.test(n) && /\}$/.test(n); } },
          { file: 'js', indent: 1, title: 'Crea el objeto de petición', instr: 'Crea <code>xhr</code> con <code>new XMLHttpRequest()</code>.', why: 'Una petición nueva en cada clic.', hint: '<code>var xhr = new XMLHttpRequest();</code>', sol: 'var xhr = new XMLHttpRequest();', ok: eq('var xhr=new XMLHttpRequest()') },
          { file: 'js', indent: 1, type: 'blank', title: 'Configura el POST', instr: 'Completa para enviar con el método <b>POST</b> al recurso <code>/books</code>.', tpl: 'xhr.open("[[POST]]", "' + URL + '/books");', blanks: ['El método para enviar datos y crear algo.'], why: '<code>POST</code> envía datos al servidor para crear un recurso nuevo (a diferencia de GET, que solo pide).', hint: 'El método es <code>POST</code>.', sol: 'xhr.open("POST", "' + URL + '/books");' },
          { file: 'js', indent: 1, title: 'Avisa que envías JSON', instr: 'Agrega la cabecera <code>Content-Type</code> con el valor <code>application/json</code>.', why: '<code>setRequestHeader(nombre, valor)</code> se llama <b>después de open</b> y <b>antes de send</b>. Le dice al servidor cómo leer el cuerpo.', hint: '<code>xhr.setRequestHeader("Content-Type", "application/json");</code>', sol: 'xhr.setRequestHeader("Content-Type", "application/json");', ok: eq("xhr.setRequestHeader('Content-Type','application/json')"), errs: [[/setrequestheader/, 'JavaScript distingue mayúsculas: es <code>setRequestHeader</code>.']] },
          { file: 'js', indent: 1, title: 'Muestra la respuesta', instr: 'En <code>xhr.onload</code>, escribe en el elemento <code>resultado</code> el <code>status</code>, un salto de línea (<code>"\\n"</code>) y el <code>responseText</code>.', multi: true, why: 'El servidor responde <b>201</b> (creado) y devuelve el libro con su nuevo <code>id</code>. Ver la respuesta confirma que funcionó.', hint: 'xhr.onload = function () {\n  document.getElementById("resultado").textContent = xhr.status + "\\n" + xhr.responseText;\n};', sol: 'xhr.onload = function () {\n  document.getElementById("resultado").textContent = xhr.status + "\\n" + xhr.responseText;\n};', ok: function (n) { return /^xhr\.onload=function\(\)\{document\.getElementById\('resultado'\)\.(?:textContent|innerText)=xhr\.status\+'\\n'\+xhr\.responseText\}$/.test(n); } },
          { file: 'js', indent: 1, title: 'Envía el libro', instr: 'Envía con <code>send</code> el objeto <code>libro</code> convertido a texto.', why: '<code>send</code> solo envía texto. <code>JSON.stringify(libro)</code> convierte el objeto en el JSON que viaja.', hint: '<code>xhr.send(JSON.stringify(libro));</code>', sol: 'xhr.send(JSON.stringify(libro));', ok: eq('xhr.send(JSON.stringify(libro))'), errs: [[/xhr\.send\(libro\)/, 'Enviarías <code>[object Object]</code>. Convierte el objeto con <code>JSON.stringify(libro)</code>.']] },
          { file: 'js', title: 'Cierra el manejador', instr: 'Cierra la función con <code>};</code>', why: 'Cierra el <code>onclick = function () {</code>.', hint: '<code>};</code>', sol: '};', ok: /^\}$/ }
        ], final: 'Escribe un título y un autor, pulsa Crear y mira el 201. Luego abre el ejemplo 5 para ver tu libro en la lista (el servidor recuerda los datos hasta que lo reinicies).' },
      /* X5 */
      { id: 'g9x5', title: 'Dos tablas: libros y ciudades', short: 'Funciones reutilizables y callbacks (análisis de resultados)', lib: null,
        goal: '<p>Es el ejercicio del <b>análisis de resultados</b> de la guía: mostrar los <code>books</code> y las <code>cities</code> en <b>dos tablas</b>. Para no repetir código, crearás una función <code>pedir(ruta, callback)</code> que sirve para cualquier recurso.</p>',
        base: { html: '<h3>Libros</h3>\n<table border="1" id="tLibros"><tr><th>Id</th><th>Título</th><th>Autor</th></tr></table>\n<h3>Ciudades</h3>\n<table border="1" id="tCiudades"><tr><th>Id</th><th>Nombre</th><th>Descripción</th></tr></table>', js: '// tu código aquí' },
        steps: [
          { file: 'js', title: 'Abre la función pedir', instr: 'Escribe la primera línea de la función <code>pedir</code> con los parámetros <code>ruta</code> y <code>callback</code>.', why: 'Un <b>callback</b> es una función que se pasa como parámetro para ejecutarse "más tarde", cuando llegue la respuesta. Así la misma función de petición sirve para libros y ciudades.', hint: '<code>function pedir(ruta, callback) {</code>', sol: 'function pedir(ruta, callback) {', ok: eq('function pedir(ruta,callback){') },
          { file: 'js', indent: 1, title: 'Prepara la petición', instr: 'Dentro: crea <code>xhr</code> y haz un GET a <code>"' + URL + '" + ruta</code>. (Dos líneas.)', multi: true, why: 'Igual que antes, pero la URL se arma con el parámetro <code>ruta</code>.', hint: 'var xhr = new XMLHttpRequest();\nxhr.open("GET", "' + URL + '" + ruta);', sol: 'var xhr = new XMLHttpRequest();\nxhr.open("GET", "' + URL + '" + ruta);', ok: function (n) { return /^(?:const|let|var) xhr=new XMLHttpRequest\(\);xhr\.open\('GET','https:\/\/mock.xidecode.dev'\+ruta(?:,true)?\)$/.test(n); } },
          { file: 'js', indent: 1, title: 'Llama al callback con los datos', instr: 'Haz que en <code>xhr.onload</code> se llame a <code>callback</code> pasándole el resultado de <code>JSON.parse(xhr.responseText)</code>.', multi: true, why: 'La función <code>pedir</code> no sabe qué hacer con los datos: se los entrega a quien la llamó mediante el <code>callback</code>.', hint: 'xhr.onload = function () {\n  callback(JSON.parse(xhr.responseText));\n};', sol: 'xhr.onload = function () {\n  callback(JSON.parse(xhr.responseText));\n};', ok: function (n) { return /^xhr\.onload=function\(\)\{callback\(JSON\.parse\(xhr\.responseText\)\)\}$/.test(n); } },
          { file: 'js', indent: 1, title: 'Envía y cierra', instr: 'Envía la petición.', why: 'Último paso dentro de la función.', hint: '<code>xhr.send();</code>', sol: 'xhr.send();', ok: /^xhr\.send\((?:null)?\)$/ },
          { file: 'js', title: 'Cierra la función', instr: 'Cierra la función con <code>}</code>.', why: 'Termina <code>pedir</code>.', hint: '<code>}</code>', sol: '}', ok: /^\}$/ },
          { file: 'js', title: 'Tabla de libros', instr: 'Llama a <code>pedir("/books", function (libros) { ... })</code>. Dentro, recorre <code>libros</code> y agrega a <code>tLibros</code> una fila <code>&lt;tr&gt;</code> con <code>id</code>, <code>title</code> y <code>author</code> en celdas <code>&lt;td&gt;</code>.', multi: true, why: 'La función anónima es el <code>callback</code>: se ejecuta cuando llegan los libros y recibe el arreglo como parámetro.', hint: 'pedir("/books", function (libros) {\n  var t = document.getElementById("tLibros");\n  for (var i = 0; i < libros.length; i++) {\n    t.innerHTML += "<tr><td>" + libros[i].id + "</td><td>" + libros[i].title + "</td><td>" + libros[i].author + "</td></tr>";\n  }\n});', sol: 'pedir("/books", function (libros) {\n  var t = document.getElementById("tLibros");\n  for (var i = 0; i < libros.length; i++) {\n    t.innerHTML += "<tr><td>" + libros[i].id + "</td><td>" + libros[i].title + "</td><td>" + libros[i].author + "</td></tr>";\n  }\n});', ok: function (n) { return /^pedir\('\/books',function\(libros\)\{/.test(n) && /tLibros/.test(n) && /libros\[\w\]\.id/.test(n) && /libros\[\w\]\.title/.test(n) && /libros\[\w\]\.author/.test(n) && /<tr>/.test(n) && /<td>/.test(n) && /\}\)$/.test(n); } },
          { file: 'js', title: 'Tabla de ciudades', instr: 'Repite la idea con <code>pedir("/cities", function (ciudades) { ... })</code> llenando <code>tCiudades</code> con <code>id</code>, <code>name</code> y <code>description</code>.', multi: true, why: 'Ya tienes la función reutilizable: solo cambia la ruta, los datos y la tabla de destino. Esa es la ventaja de separar la petición del uso de los datos.', hint: 'pedir("/cities", function (ciudades) {\n  var t = document.getElementById("tCiudades");\n  for (var i = 0; i < ciudades.length; i++) {\n    t.innerHTML += "<tr><td>" + ciudades[i].id + "</td><td>" + ciudades[i].name + "</td><td>" + ciudades[i].description + "</td></tr>";\n  }\n});', sol: 'pedir("/cities", function (ciudades) {\n  var t = document.getElementById("tCiudades");\n  for (var i = 0; i < ciudades.length; i++) {\n    t.innerHTML += "<tr><td>" + ciudades[i].id + "</td><td>" + ciudades[i].name + "</td><td>" + ciudades[i].description + "</td></tr>";\n  }\n});', ok: function (n) { return /^pedir\('\/cities',function\(ciudades\)\{/.test(n) && /tCiudades/.test(n) && /ciudades\[\w\]\.id/.test(n) && /ciudades\[\w\]\.name/.test(n) && /ciudades\[\w\]\.description/.test(n) && /<tr>/.test(n) && /\}\)$/.test(n); } }
        ], final: 'Dos tablas con una sola función de petición. Para completar el análisis de la guía, intenta (en modo libre) hacer un POST para agregar otra ciudad y recargar la tabla.' }
    ],

    quiz: [
      { q: 'La "A" de AJAX significa...', opts: ['Automático', 'Asíncrono', 'Avanzado', 'Aleatorio'], a: 1, why: 'Asynchronous: la petición no detiene la página mientras espera la respuesta.' },
      { q: '¿Qué hace <code>xhr.open("GET", url)</code>?', opts: ['Envía la petición al servidor', 'Prepara (configura) la petición, pero todavía no la envía', 'Abre una ventana nueva', 'Cierra la conexión'], a: 1, why: '<code>open</code> solo configura; el envío lo hace <code>send()</code>.' },
      { q: '¿Qué valor de <code>readyState</code> indica que la petición terminó?', opts: ['0', '1', '3', '4'], a: 3, why: 'El estado 4 (DONE) significa que se recibió toda la respuesta.' },
      { q: 'Tu <code>readyState</code> es 4 y <code>status</code> es 404. ¿Qué significa?', opts: ['Todo salió bien', 'La petición terminó pero el recurso no existe', 'Se cayó la conexión a internet', 'El servidor tuvo un error interno'], a: 1, why: '404 = Not Found. La petición sí terminó (estado 4) pero el recurso pedido no existe.' },
      { q: 'El servidor te manda un JSON como texto en <code>responseText</code>. ¿Cómo lo conviertes en objeto?', opts: ['JSON.stringify(xhr.responseText)', 'JSON.parse(xhr.responseText)', 'Number(xhr.responseText)', 'xhr.responseObject'], a: 1, why: '<code>JSON.parse</code> convierte texto JSON en objeto.' },
      { q: 'Para enviar un objeto con POST, ¿qué le pasas a <code>send</code>?', opts: ['El objeto tal cual', 'JSON.stringify(objeto)', 'JSON.parse(objeto)', 'null'], a: 1, why: '<code>send</code> envía texto: hay que convertir el objeto con <code>JSON.stringify</code>.' },
      { q: '¿Dónde debe ir el código que usa la respuesta del servidor?', opts: ['Justo después de send()', 'Antes de open()', 'Dentro de onload / onreadystatechange', 'En cualquier lugar, da igual'], a: 2, why: 'La respuesta llega más tarde; solo dentro de esos manejadores ya existe.' },
      { q: '¿Qué pasa si usas <code>open("GET", url, false)</code>?', opts: ['La petición es síncrona y congela el navegador hasta recibir respuesta', 'La petición se cancela', 'Se usa POST', 'Nada, el tercer parámetro no existe'], a: 0, why: 'false = síncrona: bloquea todo mientras espera. Por eso se evita.' }
    ]
  });
})();
